/// <summary>
/// The <c>AVAWhsWorkCreateReceivingCls_Extension</c> represents a extension of the class WhsWorkCreateReceiving
/// </summary>
[
    ExtensionOf(classStr(WhsWorkCreateReceiving))
]
final class AVAWhsWorkCreateReceivingCls_Extension
{
}

Method.Source:
/// <summary>
/// extension MEthode for registerInventTransferLineQuantities
/// and the license plate id parameters.
/// </summary>
/// <param name = "_inventTransferLine">
/// The <c>InventTransferLine</c> record that will be used for the registration.
/// </param>
/// <param name = "_licensePlateForReceiving">
/// The license plate id that will be used for find the registration.
/// </param>
/// <param name = "_qty">
/// The quantity that will be registered.
/// </param>
/// <param name = "_inventDimShipped">
/// The <c>InventDim</c> record that was already shipped.
/// </param>
/// <param name = "_cwQty">
/// The catch weight quantity that will be registered.
/// </param>
/// <remarks>
/// The method is an extension point and is not meant to be called directly. Callers should call the registerInventTransferLineHandlingQty method.
/// </remarks>
protected void registerInventTransferLineQuantities(
    InventTransferLine  _inventTransferLine,
    WHSLicensePlateId   _licensePlateForReceiving,
    InventQty           _qty,
    InventDim           _inventDimShipped,
    PdsCWInventQty      _cwQty)
{
    WHSLicensePlateId               avaLicensePlateForReceiving;
    WHSLicensePlateId               avaPostedLicensePlate;
    AVARegisterASNItemsIDisposable  avaRegisterASNItemsIDisposable;

    avaRegisterASNItemsIDisposable  = AVARegisterASNItemsIDisposable::current();
    avaLicensePlateForReceiving     = _licensePlateForReceiving;

    if (avaRegisterASNItemsIDisposable
     && avaRegisterASNItemsIDisposable.aktiveProcess == NoYes::Yes)
    {
        avaPostedLicensePlate = avaRegisterASNItemsIDisposable.loopUpLicensePlateToRegister(_licensePlateForReceiving);

        if (avaPostedLicensePlate
         && avaPostedLicensePlate != _licensePlateForReceiving)
        {
            avaLicensePlateForReceiving = avaPostedLicensePlate;
        }
    }

    next registerInventTransferLineQuantities(_inventTransferLine,
                                              avaLicensePlateForReceiving,
                                              _qty,
                                              _inventDimShipped,
                                              _cwQty);
}
